import React, { useEffect, useMemo, useState } from 'react';
import { Activity, AlertTriangle, Building2, CheckCircle2, ClipboardCheck, Download, FileText, Fingerprint, Globe, Network, Plus, Search, ShieldCheck, Trash2, UserRound, X } from 'lucide-react';
